     1→# ABOUTME: Sea of Nodes IR node representation for Chalk compiler
     2→# ABOUTME: Represents a single node in the IR graph with operation type, inputs, and attributes
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Node {
     8→    field $id         :param :reader;
     9→    field $op         :param :reader;
    10→    field $inputs     :param :reader;
    11→    field $attributes :param :reader;
    12→
    13→    method to_hash() {
    14→        return {
    15→            id         => $id,
    16→            op         => $op,
    17→            inputs     => $inputs,
    18→            attributes => $attributes,
    19→        };
    20→    }
    21→
    22→    # Helper: Check if an attribute represents a constant value
    23→    sub _is_constant($attr) {
    24→        return defined($attr) && $attr->{op} eq 'Constant';
    25→    }
    26→
    27→    # Helper: Check for integer overflow in arithmetic operations
    28→    # Returns true if operation would overflow, false otherwise
    29→    # Uses 64-bit signed integer bounds (common on modern systems)
    30→    sub _would_overflow($op, $left, $right) {
    31→        my $max_int = 9223372036854775807;   # 2^63 - 1
    32→        my $min_int = -9223372036854775808;  # -2^63
    33→
    34→        if ($op eq 'Add') {
    35→            return 1 if $left > 0 && $right > 0 && $left > $max_int - $right;
    36→            return 1 if $left < 0 && $right < 0 && $left < $min_int - $right;
