    my $const1 = Chalk::IR::Node->new(
        id => 'const_1',
        op => 'Constant',
        inputs => [],
        attributes => { value => 10, type => 'Int' }
    );
    $graph->add_node($const1);

    # Invalid: Phi references node_999 which doesn't exist
