    $graph->add_node($const1);

    my $const2 = Chalk::IR::Node->new(
        id => 'const_2',
        op => 'Constant',
        inputs => [],
        attributes => { value => 20, type => 'Int' }
    );
    $graph->add_node($const2);

    # Valid: Phi with correct number of alternatives
    my $phi = Chalk::IR::Node->new(
        id => 'node_2',
        op => 'Phi',
        inputs => ['node_1', 'const_1', 'const_2'],
        attributes => {
            region_id => 'node_1',
